#!/bin/bash

# Set the base path prefix here
BASE_PATH="/homes/projects/digital-vlsi-cad-files/tsmc18"

# Resolve project path
PROJECT_PATH="../"
PROJECT_PATH=$(realpath "$PROJECT_PATH")

# Output file name
OUTPUT_FILE="drc_run_file"

# Create the run file
cat > "$OUTPUT_FILE"_chip <<EOF
// Generated by HAMMER

LAYOUT PATH "${PROJECT_PATH}/logo/chip_top_signoff_logo.gds"
LAYOUT PRIMARY "chip_top"
LAYOUT SYSTEM GDSII

DRC RESULTS DATABASE "${PROJECT_PATH}/signoff_drc/run/db/drc_results_chip.db" ASCII
DRC MAXIMUM RESULTS 1000
DRC MAXIMUM VERTEX 4096

DRC CELL NAME YES CELL SPACE XFORM
DRC SUMMARY REPORT "${PROJECT_PATH}/signoff_drc/run/rpt/drc_results_chip.rpt" REPLACE HIER

VIRTUAL CONNECT COLON NO
VIRTUAL CONNECT REPORT NO
INCLUDE "${BASE_PATH}/tsmc18/chip_40K.calibre.drc"

DRC ICSTATION YES
EOF

echo "DRC run file generated as '$OUTPUT_FILE'_chip"

cat > "$OUTPUT_FILE"_ant <<EOF
// Generated by HAMMER

LAYOUT PATH "${PROJECT_PATH}/logo/chip_top_signoff_logo.gds"
LAYOUT PRIMARY "chip_top"
LAYOUT SYSTEM GDSII

DRC RESULTS DATABASE "${PROJECT_PATH}/signoff_drc/run/db/drc_results_ant.db" ASCII
DRC MAXIMUM RESULTS 1000
DRC MAXIMUM VERTEX 4096

DRC CELL NAME YES CELL SPACE XFORM
DRC SUMMARY REPORT "${PROJECT_PATH}/signoff_drc/run/rpt/drc_results_ant.rpt" REPLACE HIER

VIRTUAL CONNECT COLON NO
VIRTUAL CONNECT REPORT NO
INCLUDE "${BASE_PATH}/tsmc18/ant.drc"

DRC ICSTATION YES
EOF

echo "DRC run file generated as '$OUTPUT_FILE'_ant"

cat > "$OUTPUT_FILE"_wb <<EOF
// Generated by HAMMER

LAYOUT PATH "${PROJECT_PATH}/logo/chip_top_signoff_logo.gds"
LAYOUT PRIMARY "chip_top"
LAYOUT SYSTEM GDSII

DRC RESULTS DATABASE "${PROJECT_PATH}/signoff_drc/run/db/drc_results_wb.db" ASCII
DRC MAXIMUM RESULTS 1000
DRC MAXIMUM VERTEX 4096

DRC CELL NAME YES CELL SPACE XFORM
DRC SUMMARY REPORT "${PROJECT_PATH}/signoff_drc/run/rpt/drc_results_wb.rpt" REPLACE HIER

VIRTUAL CONNECT COLON NO
VIRTUAL CONNECT REPORT NO
INCLUDE "${BASE_PATH}/tsmc18/wirebond.drc"

DRC ICSTATION YES
EOF

echo "DRC run file generated as '$OUTPUT_FILE'_wb"
